INSERT INTO AdmissionTests (FacultyID, TestName, TotalMarks, TotalMarksText, IsPrimary, SubjectBreakdown, QuestionFormat, NegativeMarking, Notes) VALUES (1, N'NU Test', 100, N'100', 1, N'BS CS/AI/DS/CyberSec/SE/FinTech: Adv. Math 50% + Basic Math 20% + Analytical Skills & IQ 20% + English 10%. BBA/BS Business Analytics (same row): Basic Math 50% + Analytical Skills & IQ 25% + Essay Writing 15% + English 10% (no Adv. Math).', N'≈100 MCQs, computer-based, ~2 hrs, each section individually timed (cannot return to a previous section); +1 mark/correct, −0.25 mark/wrong', N'Yes — −0.25 marks per wrong answer (4 wrong answers cancel 1 correct mark); no penalty for blanks', N'Official: nu.edu.pk/Admissions/TestPattern (section weightings) and nu.edu.pk/Public/Downloads/TestGuide.pdf (format & negative marking), retrieved Aug 2026.');
