INSERT INTO AdmissionTests (FacultyID, TestName, TotalMarks, TotalMarksText, IsPrimary, SubjectBreakdown, QuestionFormat, NegativeMarking, Notes) VALUES (3, N'ECAT', 400, N'400', 1, N'Mathematics 30 Qs (120 marks) + Physics 30 Qs (120 marks) + Chemistry 30 Qs (120 marks) + English 10 Qs (40 marks)', N'100 MCQs total, 4 marks per question, 100 minutes', N'No — UET''s official Spring/Fall admissions advertisement confirms no negative marking and no passing threshold (some third-party prep sites incorrectly cite −0.25/−1 negative marking; the official UET document overrides this)', N'Official: admission.uet.edu.pk (Spring 2026 advertisement — ''no negative marking in ECAT''); subject/marks split per Maqsad ECAT syllabus 2026, retrieved Aug 2026.');
