INSERT INTO AdmissionTests (FacultyID, TestName, TotalMarks, TotalMarksText, IsPrimary, SubjectBreakdown, QuestionFormat, NegativeMarking, Notes) VALUES (26, N'AKU Admission Test', NULL, N'Not a single published maximum — scored across 2 separate sections (Science & Math Reasoning; Science Achievement). Note: the AKU Test does NOT replace MDCAT — a valid MDCAT score (180 marks; see KEMU/FJMU MBBS rows) is separately mandatory for every AKU MBBS applicant under PMDC rules', 1, N'Science Achievement: Biology + Chemistry + Physics content; Science & Math Reasoning: critical-thinking/reasoning items — exact per-section mark split not publicly itemized', N'≈100 MCQs total across both sections, 2 hours', N'Partial — no negative marking in the Science & Math Reasoning section; −0.25 marks per wrong answer in the Science Achievement section (Biology/Chemistry/Physics)', N'Official: aku.edu/admissions/Documents/sample-paper-MBBS.PDF and aku.edu/admissions curriculum page, retrieved Aug 2026.');
INSERT INTO AdmissionTests (FacultyID, TestName, TotalMarks, TotalMarksText, IsPrimary, SubjectBreakdown, QuestionFormat, NegativeMarking, Notes) VALUES (26, N'MDCAT', 180, N'180', 0, NULL, NULL, NULL, N'No — SAT-II and international MCAT are explicitly NOT accepted as a substitute for MDCAT; the AKU Test is an additional AKU-specific shortlisting layer, not a replacement for the mandatory national MDCAT');
