USE UniPak;

IF COL_LENGTH('Faculties', 'SemesterFee') IS NULL ALTER TABLE Faculties ADD SemesterFee NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'SourceNotes') IS NULL ALTER TABLE Faculties ADD SourceNotes NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'TestTotalMarksText') IS NULL ALTER TABLE Faculties ADD TestTotalMarksText NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'NegativeMarking') IS NULL ALTER TABLE Faculties ADD NegativeMarking NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'AlternativeTests') IS NULL ALTER TABLE Faculties ADD AlternativeTests NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'TestSubjectsBreakdown') IS NULL ALTER TABLE Faculties ADD TestSubjectsBreakdown NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'TestFormat') IS NULL ALTER TABLE Faculties ADD TestFormat NVARCHAR(MAX) NULL;
IF COL_LENGTH('Faculties', 'EntryTestSourceNotes') IS NULL ALTER TABLE Faculties ADD EntryTestSourceNotes NVARCHAR(MAX) NULL;
ALTER TABLE Faculties ALTER COLUMN HostelNote NVARCHAR(MAX) NULL;
ALTER TABLE Faculties ALTER COLUMN ApplicationMethod NVARCHAR(MAX) NULL;
ALTER TABLE Faculties ALTER COLUMN AggregateFormula NVARCHAR(MAX) NULL;
GO

IF OBJECT_ID('AdmissionTests', 'U') IS NULL
BEGIN
  CREATE TABLE AdmissionTests (
    AdmissionTestID INT IDENTITY(1,1) PRIMARY KEY,
    FacultyID INT NOT NULL,
    TestName NVARCHAR(150) NOT NULL,
    TotalMarks DECIMAL(10,2) NULL,
    TotalMarksText NVARCHAR(MAX) NULL,
    IsPrimary BIT NOT NULL DEFAULT 0,
    SubjectBreakdown NVARCHAR(MAX) NULL,
    QuestionFormat NVARCHAR(MAX) NULL,
    NegativeMarking NVARCHAR(MAX) NULL,
    Notes NVARCHAR(MAX) NULL,
    CONSTRAINT fk_admissiontests_faculty FOREIGN KEY (FacultyID) REFERENCES Faculties(FacultyID),
    CONSTRAINT uq_admissiontests_faculty_name UNIQUE (FacultyID, TestName)
  );
  CREATE INDEX idx_admissiontests_faculty ON AdmissionTests(FacultyID);
END;
GO

BEGIN TRANSACTION;
UPDATE Faculties SET FacultyName=N'School of Computing / School of Management Sciences', Duration=N'4 years', Semesters=8, SemesterFee=N'PKR 182,500–218,500 per regular semester; PKR 232,500–268,500 for the first semester (includes admission and refundable security charges).', HostelStatus='No', HostelNote=N'No on-campus hostel at the Lahore campus. Students commonly use private hostels near campus (e.g. Milad Street, Faisal Town).', ApplicationMethod=N'FAST-NUCES own Entry Test (NU Test) OR SAT OR NTS NAT-IE/NAT-ICS/NAT-ICOM/NAT-IGS (pick one)', AggregateFormula=N'Matric(SSC) 10% + FSc(HSSC) 40% + Admission Test 50%', SourceNotes=N'Official: nu.edu.pk/Admissions/EligibilityCriteria (last updated 03-Jul-2026) and nu.edu.pk/Admissions/FeeStructure (Fall 2026 rates). Fee revised each academic year — verify before paying.', TestTotalMarksText=N'100 (computer-based; some cycles report ~120 MCQs across 4 sections — confirm current-cycle format on the admit card)', NegativeMarking=N'Yes — −0.25 marks per wrong answer (4 wrong answers cancel 1 correct mark); no penalty for blanks', AlternativeTests=N'Yes — SAT-I score (subject to cycle cut-off) OR NTS NAT (matching FSc group: NAT-IE/ICS/ICOM/IGS) accepted instead of sitting the NU Test', TestSubjectsBreakdown=N'BS CS/AI/DS/CyberSec/SE/FinTech: Adv. Math 50% + Basic Math 20% + Analytical Skills & IQ 20% + English 10%. BBA/BS Business Analytics (same row): Basic Math 50% + Analytical Skills & IQ 25% + Essay Writing 15% + English 10% (no Adv. Math).', TestFormat=N'≈100 MCQs, computer-based, ~2 hrs, each section individually timed (cannot return to a previous section); +1 mark/correct, −0.25 mark/wrong', EntryTestSourceNotes=N'Official: nu.edu.pk/Admissions/TestPattern (section weightings) and nu.edu.pk/Public/Downloads/TestGuide.pdf (format & negative marking), retrieved Aug 2026.' WHERE FacultyID=1;
UPDATE Faculties SET FacultyName=N'School of Engineering', Duration=N'4 years', Semesters=8, SemesterFee=N'PKR 182,500–218,500 per regular semester; PKR 232,500–268,500 for the first semester (includes admission and refundable security charges).', HostelStatus='No', HostelNote=N'No on-campus hostel at the Lahore campus.', ApplicationMethod=N'FAST-NUCES own Entry Test (NU Test) OR SAT OR NTS NAT-IE', AggregateFormula=N'Matric(SSC) 17% + FSc(HSSC) 50% + Admission Test 33%', SourceNotes=N'Official: nu.edu.pk/Admissions/EligibilityCriteria (last updated 03-Jul-2026).', TestTotalMarksText=N'100', NegativeMarking=N'Yes — −0.25 marks per wrong answer', AlternativeTests=N'Yes — SAT-I OR NTS NAT-IE accepted instead of the NU Test', TestSubjectsBreakdown=N'Adv. Math 50% + Basic Math 20% + Analytical Skills & IQ 20% + English 10% (NU''s official ''BS CS/Engg.'' test-pattern column)', TestFormat=N'≈100 MCQs, computer-based, ~2 hrs, individually timed sections; +1/correct, −0.25/wrong', EntryTestSourceNotes=N'Official: nu.edu.pk/Admissions/TestPattern, retrieved Aug 2026.' WHERE FacultyID=2;
UPDATE Faculties SET FacultyName=N'Engineering & Computing (ECAT-based)', Duration=N'4 years', Semesters=8, SemesterFee=N'Subsidized: PKR 72,260–105,060 per semester after the first semester; first semester PKR 110,340. Partially subsidized: PKR 113,040–156,070 per semester after the first semester; first semester PKR 159,290.', HostelStatus='Yes', HostelNote=N'Yes, subject to seat availability. Dormitory ≈PKR 13,040/semester (subsidized) – 17,750 (partially subsidized); Cubicle ≈PKR 16,260–24,170/semester, + PKR 2,810 one-time hostel admission fee.', ApplicationMethod=N'ECAT (UET''s own Engineering College Admission Test) — compulsory for Engineering/Computing/Architecture', AggregateFormula=N'Matric(SSC) 17% + FSc Part-I(HSSC) 50% + ECAT 33% (min. 60% Intermediate marks required)', SourceNotes=N'Official: admission.uet.edu.pk/program/1 — Fall 2026 fee schedule & eligibility (retrieved Aug 2026). Fee rises each semester per the published schedule; confirm current year''s notice.', TestTotalMarksText=N'400 (100 MCQs × 4 marks each)', NegativeMarking=N'No — UET''s official Spring/Fall admissions advertisement confirms no negative marking and no passing threshold (some third-party prep sites incorrectly cite −0.25/−1 negative marking; the official UET document overrides this)', AlternativeTests=N'No — ECAT is compulsory for Engineering/Computing programs at UET; SAT/ACT are not accepted as substitutes', TestSubjectsBreakdown=N'Mathematics 30 Qs (120 marks) + Physics 30 Qs (120 marks) + Chemistry 30 Qs (120 marks) + English 10 Qs (40 marks)', TestFormat=N'100 MCQs total, 4 marks per question, 100 minutes', EntryTestSourceNotes=N'Official: admission.uet.edu.pk (Spring 2026 advertisement — ''no negative marking in ECAT''); subject/marks split per Maqsad ECAT syllabus 2026, retrieved Aug 2026.' WHERE FacultyID=3;
UPDATE Faculties SET FacultyName=N'Architecture', Duration=N'5 years', Semesters=10, SemesterFee=N'Subsidized: PKR 72,260–105,060 per semester; first semester PKR 110,340. Partially subsidized: PKR 113,040–160,260 per semester; first semester PKR 159,290.', HostelStatus='Yes', HostelNote=N'Yes, subject to availability (see hostel rates above).', ApplicationMethod=N'ECAT (compulsory)', AggregateFormula=N'Matric(SSC) 17% + FSc Part-I(HSSC) 50% + ECAT 33%', SourceNotes=N'Official: architecture.uet.edu.pk and admission.uet.edu.pk (retrieved Aug 2026).', TestTotalMarksText=N'400 (100 MCQs × 4 marks each)', NegativeMarking=N'No — confirmed no negative marking in ECAT (official UET admissions document)', AlternativeTests=N'No — ECAT is compulsory for Architecture at UET; SAT/ACT not accepted', TestSubjectsBreakdown=N'Mathematics 30 Qs (120 marks) + Physics 30 Qs (120 marks) + Chemistry 30 Qs (120 marks) + English 10 Qs (40 marks)', TestFormat=N'100 MCQs total, 4 marks per question, 100 minutes', EntryTestSourceNotes=N'Official: admission.uet.edu.pk and architecture.uet.edu.pk, retrieved Aug 2026.' WHERE FacultyID=4;
