UPDATE Faculties SET FacultyName=N'Suleman Dawood School of Business (SDSB)', Duration=N'4 years', Semesters=8, SemesterFee=N'PKR 788,900 per regular semester; first semester PKR 1,078,300 including admission and refundable security charges.', HostelStatus='Yes', HostelNote=N'Yes — extensive on-campus residence (13 hostel buildings: 6 for women, 7 for men). Out-of-town students given priority; hostel included free for National Outreach Programme (NOP) scholarship recipients.', ApplicationMethod=N'SAT (with Essay) or LUMS'' own LCAT, plus academic record and application profile', AggregateFormula=N'No fixed % weighted formula — holistic review of O-Level/Matric & A-Level/FSc academic record, SAT/LCAT score, and application profile (interviews for some programs).', SourceNotes=N'Official: lums.edu.pk/programmes (Admission Criteria & Fee tabs per programme, retrieved Aug 2026).', TestTotalMarksText=N'No fixed numeric maximum published — LCAT is scored/ranked on a percentile basis rather than a fixed total; SAT is scored 400–1600', NegativeMarking=N'No negative marking on either the LCAT or the SAT', AlternativeTests=N'Yes — SAT (with Essay, where required) or ACT accepted as a full alternative to the LCAT for SDSB admission', TestSubjectsBreakdown=N'LCAT: 7 sections × 25 min — 2 Verbal (reading comprehension, sentence completion, critical reasoning) + 2 Math (algebra, geometry, arithmetic, basic calculus) + 3 additional Verbal/Math sections; no essay; no fixed per-section mark allocation published', TestFormat=N'Exact MCQ count per section not publicly disclosed; total test time ≈3 hours (7 × 25-min sections)', EntryTestSourceNotes=N'Official: lums.edu.pk/programmes (Admission Criteria tabs); LCAT structure per Qallam LCAT Guide 2026 and Dogar Brothers LCAT overview, retrieved Aug 2026.' WHERE FacultyID=9;
