UPDATE Faculties SET FacultyName=N'Shaikh Ahmad Hassan School of Law (SAHSOL)', Duration=N'5 years', Semesters=10, SemesterFee=N'PKR 788,900 per regular semester; first semester PKR 1,035,500 including admission, Pakistan Bar Council, and refundable security charges.', HostelStatus='Yes', HostelNote=N'Yes (see residence details above).', ApplicationMethod=N'SAT/LCAT plus a Law-specific writing assessment and interview', AggregateFormula=N'Holistic review with significant weight on the interview/writing assessment — no fixed % formula published.', SourceNotes=N'Official: lums.edu.pk/programmes/ba-llb (retrieved Aug 2026).', TestTotalMarksText=N'No fixed numeric maximum published — LCAT/SAT plus a separately assessed Law writing component', NegativeMarking=N'No negative marking on the LCAT/SAT MCQ portion', AlternativeTests=N'Yes — SAT/LCAT plus a Law-specific writing assessment and interview; no separate SAT-only exemption route for the writing/interview stage', TestSubjectsBreakdown=N'Same 7-section LCAT structure as SDSB, PLUS a Law-specific writing assessment and interview; no MCQ-style breakdown published for the writing portion', TestFormat=N'LCAT: exact MCQ count not disclosed, ≈3 hours; writing assessment is untimed/essay-format, no MCQ count', EntryTestSourceNotes=N'Official: lums.edu.pk/programmes/ba-llb, retrieved Aug 2026.' WHERE FacultyID=12;
UPDATE Faculties SET FacultyName=N'General', Duration=N'4 years', Semesters=8, SemesterFee=N'PKR 211,300 for the first semester; PKR 204,000 for the second semester. Later semesters: PKR 215,000–236,000 per semester under the published schedule.', HostelStatus='Yes', HostelNote=N'Yes — ITU now offers hostel facilities to its students (introduced in recent years; confirm capacity/cost with the admissions office).', ApplicationMethod=N'ITU Admissions Test (own test), with exemption if a valid ECAT, SAT, USAT, NTS or GAT score is submitted', AggregateFormula=N'BS CS / BS AI: Academic Record 50% (Matric/O-Level 15% + Intermediate Part-I/A-Level 35%) + Admission Test/SAT-I/USAT 50%. (Weighting can differ slightly for other majors — verify per programme.)', SourceNotes=N'Official: itu.edu.pk/admissions/application-process/, /faqs/, /fee-structure/ (retrieved Aug 2026).', TestTotalMarksText=N'60 (BSCS/BSAI test pattern; other majors may use a similar or slightly adjusted format — confirm the current-cycle pattern PDF for your specific program)', NegativeMarking=N'No', AlternativeTests=N'Yes — ECAT, SAT, USAT, NTS, GAT, or GRE score exempts an applicant from sitting ITU''s own Admissions Test', TestSubjectsBreakdown=N'Analytical 20 Qs + Mathematics 40 Qs (Number Systems, Sets, Matrices & Determinants, Quadratic Equations, Partial Fractions, Sequences & Series, Permutation/Combination/Probability, Mathematical Induction & Binomial Theorem, Trigonometry, Analytical Geometry, Vectors, Differentiation, Integration)', TestFormat=N'60 MCQs, 1 mark each, 90 minutes, no calculators', EntryTestSourceNotes=N'Official: itu.edu.pk/wp-content/uploads/2026/03/BSCS-BSAI-Test-Pattern-2026.pdf and itu.edu.pk/admissions/application-process/, retrieved Aug 2026.' WHERE FacultyID=13;
